import { Match as M, Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as Button from "../../ui/shadcn-button";

// MODEL

export const Model = S.Struct({ count: S.Number });
export type Model = typeof Model.Type;

// MESSAGE

export const ClickedButton = m("ClickedButton");
const Message = S.Union([ClickedButton]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{ count: 0 }, []];

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      ClickedButton: () => [evo(model, { count: (count) => count + 1 }), []],
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("flex flex-col items-start gap-2")],
    [
      h.div(
        [h.Class("flex flex-wrap items-center gap-2")],
        [
          Button.view<Message>({
            onClick: ClickedButton(),
            toView: (attributes) =>
              h.button(
                [
                  ...attributes.button,
                  h.Class(`${Button.shadcnButtonClassName} px-2 py-1 text-xs`),
                ],
                ["Extra Small"]
              ),
          }),
          Button.view<Message>({
            onClick: ClickedButton(),
            toView: (attributes) =>
              h.button(
                [
                  ...attributes.button,
                  h.Class(
                    `${Button.shadcnButtonClassName} px-2.5 py-1.5 text-sm`
                  ),
                ],
                ["Small"]
              ),
          }),
          Button.view<Message>({
            onClick: ClickedButton(),
            toView: (attributes) =>
              h.button(
                [...attributes.button, h.Class(Button.shadcnButtonClassName)],
                ["Default"]
              ),
          }),
          Button.view<Message>({
            onClick: ClickedButton(),
            toView: (attributes) =>
              h.button(
                [
                  ...attributes.button,
                  h.Class(
                    `${Button.shadcnButtonClassName} px-4 py-2.5 text-lg`
                  ),
                ],
                ["Large"]
              ),
          }),
        ]
      ),
      h.span(
        [h.Class("text-sm text-gray-600")],
        [`Clicked ${model.count} time${model.count === 1 ? "" : "s"}`]
      ),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Example from "./main";

describe("shadcn Button Size example", () => {
  test("renders and handles the Size button", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.expect(Scene.role("button", { name: "Default" })).toExist(),
      Scene.expect(Scene.text("Clicked 0 times")).toExist(),
      Scene.click(Scene.role("button", { name: "Default" })),
      Scene.expect(Scene.text("Clicked 1 time")).toExist()
    );
  });
});
